interface Described {
    String label();
}

public class Main implements Described {
    private final String name;

    Main(String name) {
        this.name = name;
    }

    @Override
    public String label() {
        return "Item: " + name;
    }

    public static void main(String[] args) {
        Described entry = new Main("Lamp");
        System.out.println(entry.label());
    }
}

import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class Main {
    public static void main(String[] args) {
        var names = List.of("Ion", "Ada", "Ion");
        Map<String, Integer> counts = new HashMap<>();
