import java.nio.file.Files;
import java.nio.file.Path;
import java.time.LocalDate;

public class Main {
    public static void main(String[] args) throws Exception {
        Path file = Files.createTempFile("ion-study-", ".txt");
        try {
            LocalDate day = LocalDate.of(2026, 11, 9);
            Files.writeString(file, day.plusDays(7).toString());
            System.out.println(LocalDate.parse(Files.readString(file)));
        } finally {
            Files.deleteIfExists(file);
        }
    }
}

public class Main {
    static int remaining(int target, int completed) {
        if (target < 0 || completed < 0 || completed > target) {
            throw new IllegalArgumentException("invalid progress");
        }
        return target - completed;
    }

    public static void main(String[] args) {
        System.out.println(remaining(9, 4));
    }
}

import java.util.List;

public class Main {
    static <T> T first(List<T> values) {
        if (values.isEmpty()) {
            throw new IllegalArgumentException("values must be nonempty");
        }
        return values.get(0);
    }

    public static void main(String[] args) {
        String label = first(List.of("Algebra", "History"));
        int score = first(List.of(8, 9));
        System.out.println(label + ": " + score);
    }
}

public class Main {
    enum Status { TODO, DONE }

    record Task(String title, Status status) {
        Task {
            if (title == null || title.isBlank() || status == null) {
                throw new IllegalArgumentException("invalid task");
            }
        }
    }

    public static void main(String[] args) {
        var task = new Task("Review arrays", Status.DONE);
        System.out.println(task.title() + " [" + task.status() + "]");
    }
}

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

public class Main {
    record Task(int priority, String name) {}

    public static void main(String[] args) {
        var tasks = new ArrayList<>(List.of(
            new Task(2, "Read"), new Task(1, "Write"), new Task(1, "Build")));
        tasks.sort(Comparator.comparingInt(Task::priority).thenComparing(Task::name));
        for (Task task : tasks) System.out.println(task.name());
    }
}

