import java.util.EnumMap;
import java.util.List;
import java.util.Map;

public class Main {
    enum Status { TODO, DONE }

    static Map<Status, Integer> counts(List<Status> statuses) {
        var result = new EnumMap<Status, Integer>(Status.class);
        for (Status status : Status.values()) result.put(status, 0);
        for (Status status : statuses) result.merge(status, 1, Integer::sum);
        return Map.copyOf(result);
    }

    public static void main(String[] args) {
        var report = counts(List.of(Status.DONE, Status.TODO, Status.DONE));
        System.out.printf("todo=%d done=%d%n", report.get(Status.TODO),
                          report.get(Status.DONE));
    }
}
